        self.state.with(|s| {
            let current = s.balances.get(&user).copied().unwrap_or(0);
            s.balances.insert(user, current + amount);
            s.total_supply += amount;
        });
    }

    fn audit_matches(&self) -> bool {
        self.state.read(|s| {
            let sum: u64 = s.balances.values().copied().sum();
            sum == s.total_supply
        })
    }
}

