use adamantium::{Actor, Map, Str};

#[derive(Clone)]
struct Session {
    token: Str,
    expires_at: u64,
}

struct SessionStore {
    sessions: Actor<Map<u64, Session>>,
}

impl SessionStore {
    async fn ensure_fresh_token(&self, user_id: u64, now: u64) -> Result<Str, AuthError> {
        let current = self.sessions.read(|m| m.get(&user_id).cloned()).ok_or(AuthError::Missing)?;
        if current.expires_at > now {
            return Ok(current.token);
        }
        let refreshed = oauth_refresh(&current.token).await?;
        self.sessions.with(|m| {
            m.insert(user_id, refreshed.clone());
        });
        Ok(refreshed.token)
    }
}

