        self.refreshes.run(user_id, || async {
            let current = self.sessions.read(|m| m.get(&user_id).cloned()).ok_or(AuthError::Missing)?;
            if current.expires_at > now {
                return Ok(current.token);
            }
            let refreshed = oauth_refresh(&current.token).await?;
            self.sessions.with(|m| {
                m.insert(user_id, refreshed.clone());
            });
            Ok(refreshed.token)
        }).await
    }
}

use adamantium::Actor;

struct QuotaState {
    used: u64,
    limit: u64,
}

struct TenantQuota {
    state: Actor<QuotaState>,
}

impl TenantQuota {
    async fn submit_job(&self, cost: u64, payload: &[u8]) -> Result<(), QuotaError> {
        let allowed = self.state.read(|q| q.used.saturating_add(cost) <= q.limit);
        if !allowed {
            return Err(QuotaError::Exceeded);
        }
        enqueue_remote(payload).await?;
        self.state.with(|q| q.used += cost);
        Ok(())
    }
}

