struct Consensus {
    is_leader: bool,
    term: u64,
    commit_index: u64,
}

async fn propose(node: &Actor<Consensus>, entry: &[u8]) -> Result<u64, ConsensusError> {
    let is_leader = node.read(|c| c.is_leader);
    if !is_leader {
        return Err(ConsensusError::NotLeader);
    }
    replicate_to_quorum(entry).await?;
    let committed = node.with(|c| {
        c.commit_index += 1;
        c.commit_index
    });
    Ok(committed)
}

use adamantium::Actor;

struct Consensus {
    is_leader: bool,
    term: u64,
    commit_index: u64,
}

async fn propose(node: &Actor<Consensus>, entry: &[u8]) -> Result<u64, ConsensusError> {
    let term = node
        .read(|c| c.is_leader.then_some(c.term))
        .ok_or(ConsensusError::NotLeader)?;
    replicate_to_quorum(term, entry).await?;
    node.with(|c| {
        if !c.is_leader || c.term != term {
            return Err(ConsensusError::TermChanged);
        }
        c.commit_index += 1;
        Ok(c.commit_index)
    })
}

