}

use adamantium::{Actor, Map};

async fn transfer(
    balances: &Actor<Map<u64, u64>>,
    from: u64,
    to: u64,
    amount: u64,
) -> Result<(), TransferError> {
    balances.with(|m| {
        let current = m.get(&from).copied().unwrap_or(0);
        if current < amount {
            return Err(TransferError::Insufficient);
        }
        m.insert(from, current - amount);
        Ok(())
    })?;
    notify_clearinghouse(from, to, amount).await?;
    balances.with(|m| {
        let current = m.get(&to).copied().unwrap_or(0);
        m.insert(to, current + amount);
    });
    Ok(())
}

use adamantium::{Actor, Map};

async fn transfer(
    balances: &Actor<Map<u64, u64>>,
    from: u64,
    to: u64,
    amount: u64,
) -> Result<(), TransferError> {
    notify_clearinghouse(from, to, amount).await?;
    balances.with(|m| {
        let src = m.get(&from).copied().unwrap_or(0);
        if src < amount {
            return Err(TransferError::Insufficient);
        }
        let dst = m.get(&to).copied().unwrap_or(0);
        m.insert(from, src - amount);
        m.insert(to, dst + amount);
        Ok(())
    })
}

