}

fn transfer(from: &Actor<Account>, to: &Actor<Account>, amount: u64) -> Result<(), &'static str> {
    from.with(|a| {
        if a.balance < amount {
            return Err("insufficient");
        }
        a.balance -= amount;
        Ok(())
    })?;
    to.with(|b| b.balance += amount);
    Ok(())
}

