    a.read(|x| x.balance) + b.read(|y| y.balance)
}

use adamantium::{Actor, Map};

struct Ledger {
    accounts: Actor<Map<u64, u64>>,
}

impl Ledger {
    fn transfer(&self, from: u64, to: u64, amount: u64) -> Result<(), &'static str> {
        self.accounts.with(|m| {
            let src = m.get(&from).copied().unwrap_or(0);
            if src < amount {
                return Err("insufficient");
            }
            let dst = m.get(&to).copied().unwrap_or(0);
            m.insert(from, src - amount);
            m.insert(to, dst + amount);
            Ok(())
        })
    }

    fn total_balance(&self) -> u64 {
        self.accounts.read(|m| m.values().copied().sum())
    }
}

use std::collections::{HashMap, VecDeque};
use adamantium::{Actor, Bytes, Str};

struct Cache {
    entries: Actor<HashMap<Str, Bytes>>,
    order: Actor<VecDeque<Str>>,
    cap: usize,
}

impl Cache {
    fn insert(&self, key: Str, value: Bytes) {
        let evicted = self.order.with(|q| {
            q.push_back(key.clone());
            if q.len() > self.cap { q.pop_front() } else { None }
        });
        self.entries.with(|m| {
            if let Some(old) = evicted {
                m.remove(&old);
            }
            m.insert(key, value);
        });
    }
}

