use std::sync::atomic::{AtomicU64, Ordering};

struct WindowBounds {
    low: AtomicU64,
    high: AtomicU64,
}

impl WindowBounds {
    fn set_range(&self, low: u64, high: u64) {
        assert!(low <= high);
        self.low.store(low, Ordering::Release);
        self.high.store(high, Ordering::Release);
    }

    fn contains(&self, value: u64) -> bool {
        let lo = self.low.load(Ordering::Acquire);
        let hi = self.high.load(Ordering::Acquire);
        value >= lo && value <= hi
    }
}

use adamantium::Actor;

struct WindowBounds {
    bounds: Actor<(u64, u64)>,
}

impl WindowBounds {
    fn set_range(&self, low: u64, high: u64) {
        assert!(low <= high);
        self.bounds.with(|b| *b = (low, high));
    }

    fn contains(&self, value: u64) -> bool {
        self.bounds.read(|&(lo, hi)| value >= lo && value <= hi)
    }
}

