use std::collections::{HashMap, HashSet};
use adamantium::Actor;

struct LeaseTable {
    active: Actor<HashSet<u64>>,
    owners: Actor<HashMap<u64, u32>>,
}

impl LeaseTable {
    fn acquire(&self, key: u64, worker: u32) -> bool {
        if !self.active.with(|s| s.insert(key)) {
            return false;
        }
        self.owners.with(|m| {
            m.insert(key, worker);
        });
        true
    }

    fn release(&self, key: u64, worker: u32) {
        let is_owner = self.owners.read(|m| m.get(&key) == Some(&worker));
        if is_owner {
            self.owners.with(|m| m.remove(&key));
            self.active.with(|s| s.remove(&key));
        }
    }
}

