        self.owners.with(|m| {
            if m.contains_key(&key) {
                return false;
            }
            m.insert(key, worker);
            true
        })
    }

    fn release(&self, key: u64, worker: u32) {
        self.owners.with(|m| {
            if m.get(&key) == Some(&worker) {
                m.remove(&key);
            }
        });
    }
}

