struct DeadLetters {
    failed: Actor<Deque<Str>>,
}

impl DeadLetters {
    fn record_failure(&self, reason: Str) {
        self.failed.with(|q| {
            if q.len() >= MAX_DEAD_LETTERS {
                let _ = q.pop_front();
            }
            q.push_back(reason);
        });
    }

    fn snapshot(&self) -> Deque<Str> {
        self.failed.snapshot()
    }
}

use std::collections::BTreeMap;
use adamantium::{Actor, Str};

struct RouteMetrics {
    counts: Actor<BTreeMap<Str, u64>>,
}

impl RouteMetrics {
    fn record(&self, raw_path: Str) {
        self.counts.with(|m| {
            *m.entry(raw_path).or_insert(0) += 1;
        });
    }
}

