use std::collections::HashMap;
use adamantium::{Actor, Bytes, Reply, ReplyReceiver};

struct RpcMux {
    pending: Actor<HashMap<u64, Reply<Bytes>>>,
}

impl RpcMux {
    fn register(&self, req_id: u64) -> ReplyReceiver<Bytes> {
        let (reply, rx) = Reply::pair();
        self.pending.with(|m| {
            m.insert(req_id, reply);
        });
        rx
    }

    fn on_response(&self, req_id: u64, payload: Bytes) {
        if let Some(reply) = self.pending.with(|m| m.remove(&req_id)) {
            let _ = reply.send(payload);
        }
    }
}

use std::collections::HashMap;
use adamantium::{Actor, Bytes, Reply};

const MAX_PENDING: usize = 1024;

struct PendingGuard {
    pending: Actor<HashMap<u64, Reply<Bytes>>>,
    req_id: u64,
}

impl Drop for PendingGuard {
    fn drop(&mut self) {
        self.pending.with(|m| {
            m.remove(&self.req_id);
        });
    }
}

struct RpcMux {
    pending: Actor<HashMap<u64, Reply<Bytes>>>,
}

impl RpcMux {
    async fn call(&self, req_id: u64) -> Result<Option<Bytes>, &'static str> {
        let rx = self.pending.with(|m| {
            if m.len() >= MAX_PENDING {
                return Err("too many pending requests");
            }
            let (reply, rx) = Reply::pair();
            m.insert(req_id, reply);
            Ok(rx)
        })?;
        let _guard = PendingGuard { pending: self.pending.clone(), req_id };
        Ok(rx.receive().await)
    }

    fn on_response(&self, req_id: u64, payload: Bytes) {
        if let Some(reply) = self.pending.with(|m| m.remove(&req_id)) {
            let _ = reply.send(payload);
        }
    }
}

use adamantium::{Actor, Array, Str};

struct AuditCollector {
    records: Actor<Array<Str>>,
}

impl AuditCollector {
    fn append(&self, entry: Str) {
        self.records.with(|a| a.push(entry));
    }

    fn count(&self) -> usize {
        self.records.read(|a| a.len())
    }
}

fn summarize_window(samples: &[u64; 64]) -> Vec<u64> {
    let mut out = Vec::with_capacity(samples.len());
    for &value in samples {
        if value > 0 {
            out.push(value * 2);
        }
    }
    out
}

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

struct TokenCache {
    map: Arc<Mutex<HashMap<String, u64>>>,
}

impl TokenCache {
    fn remember(&self, token: String, user_id: u64) {
        let mut guard = self.map.lock().unwrap();
        guard.insert(token, user_id);
    }
}

use adamantium::Receiver;

fn start_collector(rx: Receiver<String>) {
    tokio::spawn(async move {
        let mut log = Vec::new();
        while let Some(event) = rx.receive().await {
            log.push(event);
        }
    });
}

use tokio::sync::broadcast;

fn make_notifier() -> broadcast::Sender<u64> {
    let (tx, _rx) = broadcast::channel(64);
    tx
}

use std::collections::VecDeque;
use std::sync::{Arc, Mutex};

struct RingLog {
    buf: Arc<Mutex<VecDeque<String>>>,
    cap: usize,
}

impl RingLog {
    fn push(&self, line: String) {
        let mut guard = self.buf.lock().unwrap();
        if guard.len() >= self.cap {
            guard.pop_front();
        }
        guard.push_back(line);
    }
}

impl Registry {
    pub fn add_subscriber(&self, id: u64, addr: std::net::SocketAddr) {
        self.table.with(|t| {
            t.insert(id, addr);
        });
    }
}

